__global__ void matmul_naive(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y*blockDim.y+threadIdx.y;
    int col = blockIdx.x*blockDim.x+threadIdx.x;
    if(row<N && col<N){ float s=0; for(int k=0;k<N;++k) s+=A[row*N+k]*B[k*N+col]; C[row*N+col]=s; }
}

#define T 32
__global__ void matmul_tiled(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N){
  __shared__ float sA[T][T], sB[T][T];
  int ty=threadIdx.y, tx=threadIdx.x;
  int row=blockIdx.y*T+ty, col=blockIdx.x*T+tx; float s=0;
  for(int t=0;t<N/T;++t){ sA[ty][tx]=A[row*N+t*T+tx]; sB[ty][tx]=B[(t*T+ty)*N+col]; __syncthreads();
    #pragma unroll
    for(int k=0;k<T;++k) s+=sA[ty][k]*sB[k][tx]; __syncthreads(); }
  C[row*N+col]=s;
}

